import os
import hashlib
import hmac
import time
import json
import tempfile
import struct
import threading
from pathlib import Path

# Configuration
SESSION_DIR = os.environ.get('SESSION_DIR', '/tmp/sessions')
_SESSION_SECRET_ENV = os.environ.get('SESSION_SECRET')
if not _SESSION_SECRET_ENV:
    # Fail closed: never fall back to a hardcoded/known key, which would
    # allow attackers to forge session HMACs.
    raise RuntimeError(
        "SESSION_SECRET environment variable must be set to a strong, secret value"
    )
SESSION_SECRET = _SESSION_SECRET_ENV
MAX_SESSION_AGE = 3600
MAX_PAYLOAD_SIZE = 4096

class SessionValidationError(Exception):
    pass

def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Timing-safe comparison to prevent side-channel attacks."""
    return hmac.compare_digest(a, b)

def compute_session_mac(session_id: str, data: bytes) -> bytes:
    """Compute HMAC-SHA256 for session integrity verification."""
    key = SESSION_SECRET.encode('utf-8')
    msg = session_id.encode('utf-8') + b'\x00' + data
    return hmac.new(key, msg, hashlib.sha256).digest()

def validate_session_id(session_id: str) -> bool:
    """Strict validation of session ID format.
    Only allows hex characters, exactly 32 bytes (64 hex chars).
    Prevents path traversal and injection attacks."""
    if not isinstance(session_id, str):
        return False
    if len(session_id) != 64:
        return False
    try:
        int(session_id, 16)
        return True
    except ValueError:
        return False

def get_session_path(session_id: str) -> str:
    """Get the filesystem path for a session file.
    Session ID is pre-validated to be hex-only, preventing traversal."""
    if not validate_session_id(session_id):
        raise SessionValidationError("Invalid session ID format")
    # Use only first 4 chars as subdirectory for sharding
    shard = session_id[:4]
    base = os.path.join(SESSION_DIR, shard)
    return os.path.join(base, session_id + '.session')

def validate_payload(data: dict) -> dict:
    """Validate and sanitize session payload data.
    Enforces type constraints and size limits."""
    if not isinstance(data, dict):
        raise SessionValidationError("Payload must be a dictionary")

    allowed_keys = {'user_id', 'username', 'role', 'created_at', 'last_access', 'csrf_token', 'preferences'}
    sanitized = {}

    for key, value in data.items():
        if key not in allowed_keys:
            continue
        if key in ('user_id', 'created_at', 'last_access'):
            if not isinstance(value, (int, float)):
                raise SessionValidationError(f"Field {key} must be numeric")
            sanitized[key] = int(value)
        elif key == 'role':
            if value not in ('user', 'admin', 'moderator'):
                raise SessionValidationError("Invalid role")
            sanitized[key] = value
        elif key == 'preferences':
            if not isinstance(value, dict):
                raise SessionValidationError("Preferences must be a dict")
            if len(json.dumps(value)) > 1024:
                raise SessionValidationError("Preferences too large")
            sanitized[key] = value
        else:
            if not isinstance(value, str):
                raise SessionValidationError(f"Field {key} must be a string")
            if len(value) > 128:
                raise SessionValidationError(f"Field {key} too long")
            sanitized[key] = value

    return sanitized

def serialize_session(session_id: str, data: dict) -> bytes:
    """Serialize session data with integrity protection.
    Format: [4-byte version][4-byte timestamp][32-byte HMAC][JSON payload]"""
    payload = json.dumps(data, separators=(',', ':')).encode('utf-8')
    if len(payload) > MAX_PAYLOAD_SIZE:
        raise SessionValidationError("Serialized session too large")

    version = struct.pack('>I', 1)
    timestamp = struct.pack('>I', int(time.time()))
    header = version + timestamp
    mac = compute_session_mac(session_id, header + payload)

    return header + mac + payload

def deserialize_session(session_id: str, raw: bytes) -> dict:
    """Deserialize and verify session data integrity."""
    if len(raw) < 40:  # 4 + 4 + 32 minimum
        raise SessionValidationError("Session data too short")

    version = struct.unpack('>I', raw[0:4])[0]
    if version != 1:
        raise SessionValidationError("Unsupported session version")

    timestamp = struct.unpack('>I', raw[4:8])[0]
    if time.time() - timestamp > MAX_SESSION_AGE:
        raise SessionValidationError("Session expired")

    stored_mac = raw[8:40]
    header_and_payload = raw[0:8] + raw[40:]
    expected_mac = compute_session_mac(session_id, header_and_payload)

    if not constant_time_compare(stored_mac, expected_mac):
        raise SessionValidationError("Session integrity check failed")

    try:
        data = json.loads(raw[40:])
    except json.JSONDecodeError:
        raise SessionValidationError("Corrupt session data")

    return data

class SessionStore:
    """Thread-safe file-based session store with integrity verification."""

    def __init__(self):
        self._lock = threading.Lock()
        self._ensure_base_dir()

    def _ensure_base_dir(self):
        """Create session directory structure."""
        os.makedirs(SESSION_DIR, mode=0o700, exist_ok=True)

    def _ensure_shard_dir(self, session_id: str):
        """Create shard subdirectory if needed."""
        shard = session_id[:4]
        shard_path = os.path.join(SESSION_DIR, shard)
        os.makedirs(shard_path, mode=0o700, exist_ok=True)

    def create_session(self, session_id: str, data: dict) -> bool:
        """Create a new session file atomically.
        Returns False if session already exists (prevents overwrite)."""
        if not validate_session_id(session_id):
            raise SessionValidationError("Invalid session ID")

        validated_data = validate_payload(data)
        validated_data['created_at'] = int(time.time())
        validated_data['last_access'] = int(time.time())

        session_path = get_session_path(session_id)
        self._ensure_shard_dir(session_id)

        serialized = serialize_session(session_id, validated_data)

        # Atomic creation using O_CREAT|O_EXCL - fails if file exists
        try:
            fd = os.open(session_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            try:
                os.write(fd, serialized)
            finally:
                os.close(fd)
            return True
        except FileExistsError:
            return False

    def read_session(self, session_id: str) -> dict:
        """Read and verify a session."""
        if not validate_session_id(session_id):
            raise SessionValidationError("Invalid session ID")

        session_path = get_session_path(session_id)

        try:
            with open(session_path, 'rb') as f:
                raw = f.read(MAX_PAYLOAD_SIZE + 40)
        except FileNotFoundError:
            raise SessionValidationError("Session not found")

        return deserialize_session(session_id, raw)

    def update_session(self, session_id: str, data: dict) -> bool:
        """Update an existing session. Verifies old session before overwrite."""
        if not validate_session_id(session_id):
            raise SessionValidationError("Invalid session ID")

        session_path = get_session_path(session_id)

        # Read existing to preserve created_at and verify integrity
        try:
            existing = self.read_session(session_id)
        except SessionValidationError:
            return False

        validated_data = validate_payload(data)
        validated_data['created_at'] = existing.get('created_at', int(time.time()))
        validated_data['last_access'] = int(time.time())

        serialized = serialize_session(session_id, validated_data)

        # Atomic write via temp file + rename
        shard = session_id[:4]
        shard_path = os.path.join(SESSION_DIR, shard)
        fd, tmp_path = tempfile.mkstemp(dir=shard_path, prefix='.sess_')
        fd_closed = False
        try:
            os.write(fd, serialized)
            os.close(fd)
            fd_closed = True
            os.replace(tmp_path, session_path)
        except Exception:
            if not fd_closed:
                try:
                    os.close(fd)
                except OSError:
                    pass
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

        return True

    def delete_session(self, session_id: str) -> bool:
        """Delete a session file."""
        if not validate_session_id(session_id):
            raise SessionValidationError("Invalid session ID")

        session_path = get_session_path(session_id)

        try:
            os.unlink(session_path)
            return True
        except FileNotFoundError:
            return False


# HTTP request handler (simplified WSGI-like interface)
def handle_request(method: str, path: str, headers: dict, body: bytes) -> tuple:
    """Handle session-related HTTP requests.
    Returns (status_code, response_headers, response_body)."""

    store = SessionStore()

    # Extract session ID from cookie
    cookie = headers.get('Cookie', '')
    session_id = None
    for part in cookie.split(';'):
        part = part.strip()
        if part.startswith('session_id='):
            session_id = part[len('session_id='):]
            break

    if path == '/session/create' and method == 'POST':
        # Generate new session ID
        new_id = hashlib.sha256(os.urandom(32)).hexdigest()

        try:
            payload = json.loads(body) if body else {}
            store.create_session(new_id, payload)
            resp_headers = {'Set-Cookie': f'session_id={new_id}; HttpOnly; Secure; SameSite=Strict'}
            return (201, resp_headers, json.dumps({'session_id': new_id}).encode())
        except SessionValidationError as e:
            return (400, {}, json.dumps({'error': str(e)}).encode())

    elif path == '/session/read' and method == 'GET':
        if not session_id:
            return (401, {}, b'{"error": "No session"}')
        try:
            data = store.read_session(session_id)
            return (200, {}, json.dumps(data).encode())
        except SessionValidationError as e:
            return (400, {}, json.dumps({'error': str(e)}).encode())

    elif path == '/session/update' and method == 'PUT':
        if not session_id:
            return (401, {}, b'{"error": "No session"}')
        try:
            payload = json.loads(body) if body else {}
            success = store.update_session(session_id, payload)
            if success:
                return (200, {}, b'{"status": "updated"}')
            return (404, {}, b'{"error": "Session not found"}')
        except SessionValidationError as e:
            return (400, {}, json.dumps({'error': str(e)}).encode())

    elif path == '/session/delete' and method == 'DELETE':
        if not session_id:
            return (401, {}, b'{"error": "No session"}')
        store.delete_session(session_id)
        resp_headers = {'Set-Cookie': 'session_id=; Max-Age=0; HttpOnly; Secure'}
        return (200, resp_headers, b'{"status": "deleted"}')

    return (404, {}, b'{"error": "Not found"}')
